import{_ as e,o,c as a,a3 as r}from"./chunks/framework.lx4Uzxpr.js";const h=JSON.parse('{"title":"ROS 2 体系：节点图与 TF 树","description":"ROS 2 的内核选择是\\"通信交给 DDS、自己只管图模型\\"——节点/话题/服务/动作四件套表达数据流，TF 树表达空间，生命周期节点表达可靠启动","frontmatter":{"title":"ROS 2 体系：节点图与 TF 树","date":"2026-10-24T00:00:00.000Z","tags":["机器人","软件","ROS"],"category":"notes","description":"ROS 2 的内核选择是\\"通信交给 DDS、自己只管图模型\\"——节点/话题/服务/动作四件套表达数据流，TF 树表达空间，生命周期节点表达可靠启动","sidebar":false},"headers":[],"relativePath":"notes/机器人/软件与中间件/ros2.md","filePath":"notes/机器人/软件与中间件/ros2.md"}'),s={name:"notes/机器人/软件与中间件/ros2.md"};function n(l,t,i,c,g,d){return o(),a("div",null,t[0]||(t[0]=[r('<h1 id="ros-2-体系" tabindex="-1">ROS 2 体系 <a class="header-anchor" href="#ros-2-体系" aria-label="Permalink to “ROS 2 体系”">​</a></h1><p><strong>一句话定义：ROS 2 = 一套图模型（节点间怎么连）+ 一个通信底座（DDS，见<a href="/notes/机器人/软件与中间件/dds" class="term-link" title="以数据为中心的分布式通信中间件（ROS 2 底层）">DDS</a>）+ 一棵空间树（TF）——它管结构和约定，不管传输本身。</strong></p><h2 id="内核-为什么-只管结构-是正确的选择" tabindex="-1">内核：为什么&quot;只管结构&quot;是正确的选择 <a class="header-anchor" href="#内核-为什么-只管结构-是正确的选择" aria-label="Permalink to “内核：为什么&quot;只管结构&quot;是正确的选择”">​</a></h2><p>ROS 1 自研通信的教训（中心化 master、无 QoS、TCP 队头阻塞）证明：<strong>通信的正确性需求复杂到必须交给专业标准</strong>。ROS 2 的内核决策是把传输层整体外包给 DDS（QoS、发现、可靠性全盘继承），自己专注三件 DDS 不理解的事：</p><ol><li><strong>图模型</strong>：机器人软件 = 一群互相订阅数据的节点。四件套各管一种数据形态——<strong>话题</strong>（持续数据流，传感器/状态）、<strong>服务</strong>（一问一答，配置查询）、<strong>动作</strong>（长任务 + 进度 + 可中止，导航/抓取）、<strong>参数</strong>（节点配置）。</li><li><strong>空间树 TF</strong>：所有坐标系按<a href="/notes/机器人/数学基础/transform-homogeneous" class="term-link" title="位姿=坐标系间关系；齐次矩阵统一旋转与平移，左右乘各有确定含义">坐标变换与齐次矩阵</a>组织成树，任意两系间的变换自动链式求解并带时间戳。</li><li><strong>节点生命周期</strong>：受控的 configure → activate → deactivate 状态机，解决&quot;订阅者还没就绪发布者就开跑&quot;的启动竞态。</li></ol><h2 id="规则与行为" tabindex="-1">规则与行为 <a class="header-anchor" href="#规则与行为" aria-label="Permalink to “规则与行为”">​</a></h2><p><strong>QoS 规则</strong>：ROS 2 的 QoS 参数直接透传 DDS——传感器流 best-effort + KEEP_LAST(1)，指令流 reliable + KEEP_LAST(1)，参数/地图 transient_local。配错的后果与排查见<a href="/notes/机器人/软件与中间件/dds" class="term-link" title="以数据为中心的分布式通信中间件（ROS 2 底层）">DDS</a>第 4.1 节。</p><p><strong>TF 规则</strong>：</p><ol><li>树不能有环、每个坐标系唯一父节点——违反即变换无定义；</li><li>每条边带时间戳，查询时按时间外推/插值——所以发布 TF <strong>必须带正确采集时刻</strong>（时间戳语义见<a href="/notes/机器人/软件与中间件/time-sync-replay" class="term-link" title="时间戳在采集层打、全链路透传；录包把现场变成可重放数据">数据回放与时间同步</a>）；</li><li>静态外参（传感器安装）用 static TF 一次性发布，动态外参（里程计）按频率发布——<a href="/notes/机器人/感知与估计/sensor-calibration" class="term-link" title="估计内参与外参使多源数据自洽；手眼标定 AX=XB">传感器标定</a>的产出写入这里。</li></ol><p><strong>回调与执行器规则</strong>：节点的回调默认单线程排队执行——回调里写阻塞代码会冻结整个节点（控制频率掉零）。高频率控制环要么独立线程 + 独立执行器，要么沉到实时层（<a href="/notes/机器人/硬件与电子/embedded-rtos" class="term-link" title="按优先级抢占调度，保证最坏情况响应时间而非吞吐">嵌入式与 RTOS</a>）走桥接。</p><p><strong>包结构规则</strong>：colcon 包 = 代码 + package.xml（依赖声明）+ CMake。依赖关系即构建顺序——&quot;能编译&quot;不等于&quot;依赖写对了&quot;，运行期的发现失败常源于 package.xml 漏声明。</p><h2 id="抽象-组件化与部署自由" tabindex="-1">抽象：组件化与部署自由 <a class="header-anchor" href="#抽象-组件化与部署自由" aria-label="Permalink to “抽象：组件化与部署自由”">​</a></h2><p>抽象层是<strong>组件（composable node）</strong>：同一个节点代码，既能编译成独立进程（故障隔离），也能动态加载进容器进程（零拷贝、省开销）——部署形态是运行期决定而非编译期。再往上，launch 系统把&quot;哪些节点、什么参数、什么 QoS、什么 remap&quot;写成可组合的启动描述。至此机器人软件的开发循环完整：<strong>节点写逻辑 → QoS 定契约 → TF 定空间 → launch 定拓扑</strong>——与本站<a href="/notes/机器人/软件与中间件/architecture-patterns" class="term-link" title="状态归谁写、数据往哪流、故障在哪隔离——三个决策定架构">软件架构模式</a>的分层原则互为表里。</p>',13)]))}const p=e(s,[["render",n]]);export{h as __pageData,p as default};
